class Solution:
    def findMaxForm(self, strs: List[str], m: int, n: int) -> int:
        dp = [[0] * (n + 1) for _ in range(m + 1)]
        for s in strs:
            zeros = s.count("0")
            ones = len(s) - zeros
            for z in range(m, zeros - 1, -1):
                row, src = dp[z], dp[z - zeros]
                for o in range(n, ones - 1, -1):
                    if src[o - ones] + 1 > row[o]:
                        row[o] = src[o - ones] + 1
        return dp[m][n]

